@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#f4f4f0;--muted:#a9b5c3;--gold:#ffcf80;--cyan:#83e5ff;--night:#07111e;--line:rgba(255,255,255,.16)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--night);color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game-shell{position:relative;width:100vw;height:100dvh;min-height:440px;overflow:hidden;background:radial-gradient(ellipse at 75% 35%,#263148,#08121f 68%)}#game-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(5,12,23,.42),transparent 25%,transparent 68%,rgba(4,11,20,.62)),radial-gradient(ellipse at center,transparent 35%,rgba(2,7,16,.22) 100%);z-index:1}.topbar{position:absolute;z-index:4;top:0;left:0;right:0;height:82px;padding:0 clamp(22px,5.2vw,84px);display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.11);background:linear-gradient(180deg,rgba(5,12,22,.58),transparent)}.brand{display:flex;gap:12px;align-items:center;text-decoration:none;color:#f4f4f0;font:700 12px 'Space Grotesk',sans-serif;letter-spacing:.17em}.brand b{color:var(--gold);font-size:15px}.brand-mark{width:24px;height:24px;border:1px solid rgba(255,207,128,.72);border-radius:50%;display:grid;place-items:center;position:relative}.brand-mark i{position:absolute;width:2px;height:14px;background:var(--gold);border-radius:2px;transform:rotate(36deg)}.brand-mark i:nth-child(2){transform:rotate(-36deg)}.brand-mark i:nth-child(3){width:14px;height:2px;transform:rotate(0)}.chapter-label{position:absolute;left:50%;transform:translateX(-50%);text-align:center;display:grid;gap:4px}.eyebrow{font:600 9px 'Space Grotesk',sans-serif;letter-spacing:.18em;color:#aab8c8}.chapter-label strong{font:500 14px 'Space Grotesk',sans-serif;letter-spacing:.04em}.icon-button{width:38px;height:38px;border:1px solid var(--line);border-radius:50%;background:rgba(10,20,33,.3);cursor:pointer;color:var(--gold);font-size:17px}.hud{position:absolute;z-index:4;top:103px;left:clamp(22px,5.2vw,84px);right:clamp(22px,5.2vw,84px);display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none}.hero-status{display:flex;gap:12px;align-items:center}.avatar{width:38px;height:38px;border-radius:50%;border:1px solid rgba(131,229,255,.6);display:grid;place-items:center;color:#a8f0ff;background:rgba(30,82,99,.48);font:600 15px 'Space Grotesk';box-shadow:0 0 24px rgba(88,214,255,.18)}.status-copy{width:150px;display:grid;gap:8px}.status-copy .eyebrow{font-size:9px;color:#e3e7e8}.health-track,.progress-track{height:3px;background:rgba(255,255,255,.24);overflow:hidden}.health-track i{height:100%;display:block;background:linear-gradient(90deg,#ff9a76,#ffdb8d);width:100%;transition:width .25s}.objective{position:absolute;left:50%;transform:translateX(-50%);top:-4px;display:flex;gap:12px;align-items:center;padding:11px 17px;border:1px solid rgba(255,255,255,.17);background:rgba(5,13,22,.54);backdrop-filter:blur(12px);min-width:220px}.objective-icon{font-size:19px;color:var(--gold)}.objective div{display:grid;gap:4px}.objective .eyebrow{font-size:8px}.objective strong{font:500 13px 'Space Grotesk';white-space:nowrap}.progress{display:grid;gap:8px;text-align:right;font:500 10px 'Space Grotesk';letter-spacing:.13em;color:#e5e8e7}.progress-track{width:100px;height:2px}.progress-track i{height:100%;display:block;background:var(--gold);width:20%;transition:width .3s}.screen{position:absolute;inset:0;z-index:5;display:flex;align-items:center;pointer-events:auto}.hidden{display:none!important}.intro-screen{padding:105px clamp(25px,11vw,170px) 110px;background:linear-gradient(90deg,rgba(5,12,22,.91) 0%,rgba(5,12,22,.74) 38%,rgba(5,12,22,.07) 77%),linear-gradient(0deg,rgba(5,12,22,.35),transparent 45%)}.intro-copy{max-width:560px;position:relative;z-index:2;margin-top:8px}.kicker{display:flex;gap:10px;align-items:center;font:600 9px 'Space Grotesk';letter-spacing:.22em;color:#b9c9d1}.kicker span{display:inline-block;width:25px;height:1px;background:var(--gold)}h1,h2{font-family:'Space Grotesk',sans-serif;font-weight:500;letter-spacing:-.06em}h1{font-size:clamp(58px,8.5vw,116px);line-height:.86;margin:26px 0 22px}h1 em,h2 em{font-weight:400;color:var(--gold)}.intro-copy>p{max-width:410px;font-size:15px;line-height:1.75;color:#c3cbd2;margin:0 0 31px}.primary-button{display:inline-flex;align-items:center;justify-content:space-between;gap:34px;background:#f3c987;color:#161b22;padding:14px 18px;border:0;min-width:218px;font:700 11px 'Space Grotesk';letter-spacing:.02em;cursor:pointer;transition:background .2s,transform .2s}.primary-button span{font-size:17px}.primary-button:hover{background:#ffdfaa;transform:translateY(-2px)}.intro-meta{display:flex;gap:26px;margin-top:42px;font:600 8px 'Space Grotesk';letter-spacing:.13em;color:#9eacb8}.intro-meta span+span{color:#738392}.intro-side{position:absolute;right:10%;top:16%;width:min(36vw,460px);aspect-ratio:1;border-radius:50%;display:grid;place-items:center;opacity:.85}.sun-core{width:28%;aspect-ratio:1;background:radial-gradient(circle at 35% 33%,#fff5cd,#ffc47a 30%,#ee7a66 68%,rgba(176,65,112,.2));border-radius:50%;box-shadow:0 0 55px 15px rgba(255,181,125,.31),0 0 180px 40px rgba(97,139,220,.2);animation:pulse 5s ease-in-out infinite}.orbit{position:absolute;border:1px solid rgba(228,211,198,.34);border-radius:50%;width:86%;height:42%;transform:rotate(-32deg)}.orbit-two{width:107%;height:58%;transform:rotate(28deg);border-color:rgba(150,207,235,.25)}.side-caption{position:absolute;right:-18%;bottom:7%;font:600 9px/1.6 'Space Grotesk';letter-spacing:.2em;color:#c4cbd0}.controls-note{position:absolute;left:clamp(25px,5.2vw,84px);bottom:40px;font:600 9px 'Space Grotesk';letter-spacing:.13em;color:#aeb8bf}.controls-note span:not(.key-sep){display:inline-block;border:1px solid rgba(255,255,255,.3);padding:5px 7px;margin:0 5px 0 12px;color:#e2e5e5}.key-sep{color:#60717d}.game-footer{position:absolute;z-index:4;bottom:0;left:0;right:0;height:34px;padding:0 clamp(22px,5.2vw,84px);display:flex;justify-content:space-between;align-items:center;border-top:1px solid rgba(255,255,255,.1);font:600 8px 'Space Grotesk';letter-spacing:.16em;color:#8493a0;pointer-events:none}.game-footer b{color:#d7c096;font-weight:600}.story-screen{align-items:flex-end;justify-content:flex-start;padding:0 0 72px clamp(26px,11vw,170px);background:linear-gradient(0deg,rgba(4,10,19,.9),rgba(4,10,19,.45) 50%,transparent 100%)}.story-card{max-width:630px;border-left:1px solid var(--gold);padding:4px 0 4px 28px;animation:rise .5s ease both}.story-index{font:600 9px 'Space Grotesk';letter-spacing:.2em;color:var(--gold)}.story-index span{color:#87929c;margin:0 7px}.story-card h2{font-size:clamp(35px,5vw,57px);line-height:1;margin:13px 0}.story-card p{max-width:580px;color:#d0d5d9;font-size:14px;line-height:1.7;margin:0 0 19px}.story-footer{display:flex;align-items:center;justify-content:space-between;gap:20px}.story-footer>span{font:italic 11px 'DM Sans';color:#a7b2ba}.story-footer .primary-button{min-width:158px;padding:12px 15px}.chapter-banner{position:absolute;z-index:5;top:22%;left:50%;transform:translate(-50%,-10px);padding:10px 22px;border:1px solid rgba(255,207,128,.45);background:rgba(6,15,25,.75);backdrop-filter:blur(8px);font:600 10px 'Space Grotesk';letter-spacing:.22em;color:var(--gold);opacity:0;transition:all .4s;pointer-events:none}.chapter-banner.show{opacity:1;transform:translate(-50%,0)}.interact-hint{position:absolute;z-index:4;left:50%;bottom:15%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;color:#fff;font-size:11px;text-shadow:0 2px 6px #000}.interact-hint kbd{font:600 11px 'Space Grotesk';padding:7px 9px;border:1px solid rgba(255,255,255,.65);background:rgba(5,12,20,.7)}.crosshair{position:absolute;z-index:3;left:50%;top:50%;width:24px;height:24px;transform:translate(-50%,-50%);border:1px solid rgba(255,228,175,.75);border-radius:50%;pointer-events:none}.crosshair i{position:absolute;width:3px;height:3px;border-radius:50%;background:#ffe5af;left:50%;top:50%;transform:translate(-50%,-50%)}.toast{position:absolute;z-index:6;left:50%;top:20%;transform:translateX(-50%);padding:11px 17px;background:rgba(5,14,24,.78);border:1px solid rgba(255,255,255,.18);font:500 11px 'Space Grotesk';color:#e8e5df;letter-spacing:.04em;backdrop-filter:blur(8px);white-space:nowrap}.ending-screen{justify-content:center;text-align:center;background:radial-gradient(ellipse at center,rgba(12,28,47,.82),rgba(4,10,19,.94) 67%)}.ending-content{max-width:650px;padding:30px}.ending-sigil{font:300 53px 'Space Grotesk';color:var(--gold);margin-bottom:13px;text-shadow:0 0 28px rgba(255,207,128,.7)}.ending-content h2{font-size:clamp(46px,7vw,80px);line-height:.96;margin:19px 0}.ending-content>p{color:#bac5ce;font-size:14px;line-height:1.7;max-width:440px;margin:0 auto 25px}.ending-stats{display:flex;justify-content:center;gap:35px;margin:27px 0 30px}.ending-stats span{display:grid;gap:6px;font:600 8px 'Space Grotesk';letter-spacing:.15em;color:#8f9ca7}.ending-stats b{font:500 18px 'Space Grotesk';letter-spacing:.04em;color:#f1d6a5}.pause-overlay{position:absolute;inset:0;z-index:7;background:rgba(5,10,17,.75);backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:25px;font:600 12px 'Space Grotesk';letter-spacing:.25em}.damage-flash,#damage-flash{position:absolute;inset:0;z-index:3;pointer-events:none;box-shadow:inset 0 0 0 0 rgba(255,70,70,0);transition:box-shadow .12s}.#damage-flash{display:none}.mobile-controls{display:none}.move-pad,.mobile-action{touch-action:none;user-select:none}.ending-screen~.game-footer{z-index:6}
@keyframes pulse{0%,100%{transform:scale(.96);box-shadow:0 0 55px 15px rgba(255,181,125,.3),0 0 180px 40px rgba(97,139,220,.18)}50%{transform:scale(1.04);box-shadow:0 0 75px 24px rgba(255,181,125,.43),0 0 220px 60px rgba(97,139,220,.24)}}@keyframes rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:700px){.topbar{height:68px;padding:0 20px}.chapter-label{left:auto;right:66px;transform:none;text-align:right}.chapter-label .eyebrow{font-size:7px}.chapter-label strong{font-size:11px}.brand{font-size:10px}.brand-mark{width:21px;height:21px}.intro-screen{padding:100px 25px 120px;background:linear-gradient(90deg,rgba(5,12,22,.87),rgba(5,12,22,.53)),linear-gradient(0deg,rgba(5,12,22,.56),transparent)}.intro-copy{margin-top:-15px}.intro-copy>p{max-width:330px;font-size:13px}.intro-side{width:68vw;right:-11%;top:14%;opacity:.55}.side-caption{display:none}h1{font-size:clamp(58px,17vw,92px);margin:22px 0}.intro-meta{flex-direction:column;gap:9px;margin-top:27px;font-size:7px}.controls-note{left:25px;bottom:58px;font-size:7px;letter-spacing:.07em}.controls-note span:not(.key-sep){margin-left:5px;padding:4px}.game-footer{height:28px;padding:0 17px;font-size:6px}.hud{top:84px;left:18px;right:18px}.avatar{width:32px;height:32px}.status-copy{width:100px}.status-copy .eyebrow{font-size:7px}.objective{top:51px;left:0;transform:none;min-width:unset;padding:8px 11px}.objective strong{font-size:11px}.objective .eyebrow{font-size:7px}.progress{padding-top:2px;font-size:8px}.progress-track{width:68px}.story-screen{padding:0 23px 65px;background:linear-gradient(0deg,rgba(4,10,19,.94),rgba(4,10,19,.56) 65%,transparent)}.story-card{padding-left:17px}.story-card h2{font-size:38px}.story-card p{font-size:12px;line-height:1.6}.story-footer{align-items:flex-start;flex-direction:column;gap:12px}.story-footer>span{font-size:10px}.story-footer .primary-button{min-width:145px}.mobile-controls{display:flex;position:absolute;z-index:4;inset:auto 0 42px;align-items:flex-end;justify-content:space-between;padding:0 24px;pointer-events:none}.move-pad{width:92px;height:92px;border:1px solid rgba(255,255,255,.38);border-radius:50%;background:rgba(8,19,30,.35);display:grid;place-items:center;color:rgba(255,255,255,.7);font-size:23px;pointer-events:auto}.mobile-action{width:54px;height:54px;border:1px solid rgba(255,255,255,.5);border-radius:50%;background:rgba(8,19,30,.56);color:#fff;font-size:20px;pointer-events:auto}.fire-action{background:rgba(218,161,91,.58);border-color:rgba(255,217,158,.85);margin-left:-58px;margin-bottom:58px;color:#ffe4b2}.ending-stats{gap:20px}.ending-content{padding:23px}.toast{max-width:85vw;white-space:normal;text-align:center;font-size:10px}.interact-hint{bottom:22%}}
@media(max-height:560px) and (min-width:701px){.intro-screen{padding-top:82px;padding-bottom:58px}.intro-copy>p{margin-bottom:18px}.intro-meta{margin-top:22px}.controls-note{bottom:38px}h1{font-size:64px;margin:16px 0}.intro-side{width:35vw;top:9%}.story-screen{padding-bottom:50px}.story-card h2{font-size:40px}.story-card p{margin-bottom:12px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const $ = (id) => document.getElementById(id);
const canvas = $('game-canvas');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.8));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;

const scene = new THREE.Scene();
scene.background = new THREE.Color('#101b2c');
scene.fog = new THREE.FogExp2('#101b2c', 0.015);
const camera = new THREE.PerspectiveCamera(54, window.innerWidth / window.innerHeight, 0.1, 160);
camera.position.set(0, 6, 12);
const clock = new THREE.Clock();
const world = new THREE.Group(); scene.add(world);
const dynamicWorld = new THREE.Group(); scene.add(dynamicWorld);
const hemi = new THREE.HemisphereLight('#bcd5ef', '#192130', 1.35); scene.add(hemi);
const sun = new THREE.DirectionalLight('#ffd6ae', 3.2); sun.position.set(-12, 24, 10); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -28; sun.shadow.camera.right = 28; sun.shadow.camera.top = 28; sun.shadow.camera.bottom = -28; scene.add(sun);
const fill = new THREE.PointLight('#4c9dce', 35, 40, 2); fill.position.set(4, 7, -4); scene.add(fill);

const mat = (color, roughness = .78, metalness = .05, emissive = null, intensity = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness, emissive: emissive || color, emissiveIntensity: intensity });
const mats = {
  ground: mat('#172331'), road: mat('#17202b'), sidewalk: mat('#36404a'), building: mat('#263445'), building2: mat('#303b4b'), window: new THREE.MeshStandardMaterial({ color: '#f1b878', emissive: '#ffb761', emissiveIntensity: 1.7, roughness: .4 }),
  hero: mat('#253c53', .54, .12), heroDark: mat('#111d2a', .64, .1), skin: mat('#d29a72'), hair: mat('#25202a'), gold: mat('#ffd58d', .28, .5, '#ffb64f', 1.4), cyan: mat('#84e9ff', .22, .2, '#4cd9ff', 2.8), enemy: mat('#211d36', .36, .34, '#8e3cff', 1.25), enemyEye: mat('#ff7a91', .25, .1, '#ff315e', 3), white: mat('#f3eee1', .4)
};

const state = { running:false, paused:false, stage:-1, health:100, hits:0, startTime:0, fireHeld:false, lastShot:0, lastDamage:0, keys:new Set(), player:null, playerParts:null, interact:null, enemies:[], collectibles:[], anchors:[], projectiles:[], decor:[], mobileVector:new THREE.Vector2(), touchStart:null, sound:false, stageComplete:false };
const chapters = [
  { name:'Una vida normal', index:'CAPÍTULO 01', date:'CINCO AÑOS ANTES', title:'Un día cualquiera', body:'Alex Ríos no era especial. Pagaba la renta, llegaba tarde al trabajo y guardaba los domingos para Inés. Hasta que una grieta en el cielo eligió su camino de regreso a casa.', quote:'A veces el universo te encuentra en el momento más común.', objective:'Llega a la estación de metro', label:'HUMANO', theme:0 },
  { name:'El primer destello', index:'CAPÍTULO 02', date:'LA NOCHE DEL DESPERTAR', title:'La luz también quema', body:'La grieta lo alcanzó. Alex sobrevivió, pero algo antiguo despertó en sus manos: energía capaz de cerrar los bordes rotos del mundo. El poder no vino con instrucciones.', quote:'No sabía qué podía hacer. Solo sabía a quién quería proteger.', objective:'Reúne los 3 fragmentos de luz', label:'DESPERTANDO', theme:1 },
  { name:'Aprender a volar', index:'CAPÍTULO 03', date:'MESES DESPUÉS', title:'El poder se aprende', body:'Con ayuda de una pequeña comunidad de héroes, Alex aprendió a controlar cada pulso. Falló, volvió a intentarlo y, por primera vez, dejó de tener miedo de sus propias manos.', quote:'El valor no era no caer. Era levantarse con más cuidado.', objective:'Cierra las 5 fisuras', label:'PORTADOR DE LUZ', theme:2 },
  { name:'Un lugar que llamar hogar', index:'CAPÍTULO 04', date:'DOCE AÑOS DESPUÉS', title:'Todo lo que importa', body:'Alex e Inés construyeron una vida. Su hija Luna llenó la casa de dibujos de estrellas y preguntas imposibles. Alex aprendió que ser héroe también era estar presente cuando se apagaban las luces.', quote:'Su mayor hazaña no tenía capa: era volver a casa.', objective:'Protege el vecindario', label:'GUARDIÁN', theme:3 },
  { name:'La última frontera', index:'CAPÍTULO 05', date:'EL FIN DE TODOS LOS MUNDOS', title:'La noche de mil cielos', body:'La amenaza se llamaba NÉMESIS: una conciencia que devoraba universos para silenciar el dolor. Alex y un grupo de héroes resistieron juntos, pero la última fisura solo podía cerrarse desde dentro.', quote:'Hay sacrificios que no son una despedida. Son una promesa.', objective:'Desactiva los 3 anclajes', label:'ÚLTIMO GUARDIÁN', theme:4 }
];

function resize(){ renderer.setSize(window.innerWidth, window.innerHeight); camera.aspect = window.innerWidth/window.innerHeight; camera.updateProjectionMatrix(); }
window.addEventListener('resize', resize);

function showStory(stage){
  state.stage = stage;
  const chapter = chapters[stage];
  $('chapter-name').textContent = chapter.name;
  $('story-index').innerHTML = `${chapter.index} <span>—</span> ${chapter.date}`;
  $('story-title').textContent = chapter.title;
  $('story-body').textContent = chapter.body;
  $('story-quote').textContent = `“${chapter.quote}”`;
  $('story-screen').classList.remove('hidden');
  $('intro-screen').classList.add('hidden');
  $('ending-screen').classList.add('hidden');
  $('hud').classList.add('hidden');
  $('mobile-controls').classList.add('hidden');
  $('interact-hint').classList.add('hidden');
  $('crosshair').classList.add('hidden');
}

$('start-button').addEventListener('click',()=>{ state.startTime=performance.now(); state.health=100; state.hits=0; showStory(0); });
$('continue-button').addEventListener('click',beginStage);
$('restart-button').addEventListener('click',()=>{ state.health=100;state.hits=0;state.startTime=performance.now();state.running=false;state.stage=-1;$('ending-screen').classList.add('hidden');$('intro-screen').classList.remove('hidden');$('chapter-name').textContent='Una vida normal'; });
$('resume-button').addEventListener('click',togglePause);
$('sound-button').addEventListener('click',()=>{state.sound=!state.sound;$('sound-button').style.color=state.sound?'#83e5ff':'#ffcf80';showToast(state.sound?'Audio ambiental activado':'Audio ambiental silenciado');});

function beginStage(){
  $('story-screen').classList.add('hidden');
  state.running=true;state.paused=false;state.stageComplete=false;
  $('hud').classList.remove('hidden');
  if(window.matchMedia('(pointer:coarse)').matches) $('mobile-controls').classList.remove('hidden');
  $('crosshair').classList.remove('hidden');
  buildStage(state.stage);
  $('chapter-name').textContent=chapters[state.stage].name;
  $('power-label').textContent=`· ${chapters[state.stage].label}`;
  $('objective-text').textContent=chapters[state.stage].objective;
  updateHUD();
  showBanner(`${chapters[state.stage].index}  /  ${chapters[state.stage].name.toUpperCase()}`);
}

function showBanner(text){const el=$('chapter-banner');el.textContent=text;el.classList.remove('hidden');requestAnimationFrame(()=>el.classList.add('show'));setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.classList.add('hidden'),500);},2300);}
let toastTimer;
function showToast(text){const el=$('toast');el.textContent=text;el.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hidden'),1800);}
function updateHUD(){ $('health-fill').style.width=`${Math.max(0,state.health)}%`; $('progress-text').textContent=`0${state.stage+1} / 05`; $('progress-fill').style.width=`${(state.stage+1)*20}%`; }

function clearGroup(group){ while(group.children.length){const o=group.children.pop();if(o.geometry)o.geometry.dispose();if(o.material && !Array.isArray(o.material))o.material.dispose();} }
function addMesh(parent,geometry,material,x=0,y=0,z=0){const mesh=new THREE.Mesh(geometry,material);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);return mesh;}
function box(parent,w,h,d,material,x,y,z){return addMesh(parent,new THREE.BoxGeometry(w,h,d),material,x,y,z);}
function makeGround(){
  const ground=addMesh(world,new THREE.PlaneGeometry(150,150),mats.ground,0,-.12,0);ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;
  const road=addMesh(world,new THREE.PlaneGeometry(11,70),mats.road,0,-.08,-1);road.rotation.x=-Math.PI/2;
  const grid=new THREE.GridHelper(100,50,'#52657b','#293849');grid.position.y=-.065;grid.material.opacity=.2;grid.material.transparent=true;world.add(grid);
  for(let z=-30;z<33;z+=7){box(world,.12,.02,3.2,mat('#78818a'),0,-.045,z);}
  for(const x of [-6.4,6.4]){const curb=box(world,.35,.2,70,mats.sidewalk,x,-.01,-1);curb.castShadow=false;}
}
function building(x,z,w,h,d,index){
