const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--enable-gpu','--ignore-gpu-blocklist','--enable-unsafe-swiftshader','--no-sandbox']});
 const page=await browser.newPage({viewport:{width:960,height:540},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push('pageerror '+e.message));page.on('console',m=>{if(m.type()==='error')errors.push('console '+m.text())});page.on('response',r=>{if(r.status()>=400)errors.push(`${r.status()} ${r.url()}`)});
 await page.route('**/game.js',async route=>{const res=await route.fetch();let body=await res.text();body=body.replace('const chapters = [','window.__gameState=state;window.__testHit=hitTarget;\nconst chapters = [');await route.fulfill({response:res,body});});
 await page.goto('http://localhost:3002/',{waitUntil:'networkidle'});
 const wait=ms=>page.waitForTimeout(ms), visible=()=>page.locator('#story-screen').isVisible(), advance=async()=>{await page.locator('#continue-button').click();await wait(180)};
 await page.locator('#start-button').click();await advance();
 await page.evaluate(()=>window.__gameState.player.position.set(0,0,-15));await page.keyboard.press('e');await wait(250);console.log('Chapter 1:',await visible());await advance();
 for(let i=0;i<3;i++){await page.evaluate(i=>window.__gameState.player.position.copy(window.__gameState.collectibles[i].group.position),i);await wait(180)}await wait(250);console.log('Chapter 2:',await visible());await advance();
 await page.evaluate(()=>window.__gameState.enemies.slice().forEach(e=>window.__testHit(e)));await wait(250);console.log('Chapter 3:',await visible());await advance();
 await page.evaluate(()=>window.__gameState.enemies.slice().forEach(e=>window.__testHit(e)));await wait(250);console.log('Chapter 4:',await visible());await advance();
 await page.evaluate(()=>window.__gameState.anchors.slice().forEach(a=>window.__testHit(a)));await page.evaluate(()=>window.__gameState.enemies.slice().forEach(e=>window.__testHit(e)));await wait(250);console.log('Chapter 5 objective:',await page.locator('#objective-text').innerText());
 await page.evaluate(()=>window.__gameState.player.position.set(0,0,-18));await page.keyboard.press('e');await wait(250);console.log('Epilogue:',await visible());await advance();await wait(300);
 console.log('Ending:',await page.locator('#ending-screen').isVisible(),'Footer hidden:',await page.locator('#game-footer').evaluate(e=>getComputedStyle(e).display==='none'));
 await page.screenshot({path:'/tmp/opencode/final-ending.jpg',type:'jpeg',quality:82});console.log('Errors:',errors);
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

